import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ApiService } from '../../services/api.service';
import { HomeResponse } from '../../models/models';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './home.component.html',
  styleUrl: './home.component.css'
})
export class HomeComponent implements OnInit {
  homeData: HomeResponse | null = null;
  loading = true;
  error: string | null = null;

  constructor(private apiService: ApiService) { }

  ngOnInit(): void {
    this.loadHomeData();
  }

  loadHomeData(): void {
    this.apiService.getHome().subscribe({
      next: (data) => {
        this.homeData = data;
        this.loading = false;
      },
      error: (err) => {
        console.error('Error loading home data:', err);
        this.error = 'Failed to load home data';
        this.loading = false;
      }
    });
  }
}
<div class="home-container">
  <div *ngIf="loading" class="loading">Loading...</div>
  <div *ngIf="error" class="error">{{ error }}</div>
  <div *ngIf="homeData && !loading" class="home-content">
    <h1>{{ homeData.title }}</h1>
    <p>{{ homeData.description }}</p>
    <p class="welcome-name">Welcome, {{ homeData.name }}</p>
  </div>
</div>
